package main

import (
	"fmt"
	"strings"

	"github.com/pg-sage/sidecar/internal/metricsreg"
)

// Markers around the rename table; docs/deployment.md carries the same
// table between them, and the docs-name test allows retired names only
// inside them.
const (
	renamesStart = "<!-- metrics-renames:start -->"
	renamesEnd   = "<!-- metrics-renames:end -->"
	rulesURL     = "https://github.com/jasonmassie01/pg_sage/blob/master/deploy/prometheus/"
)

const header = `# Metrics reference

<!-- Generated by sidecar/cmd/gen_metrics_doc from sidecar/internal/metricsreg;
do not edit. Regenerate with: cd sidecar && go generate ./internal/metricsreg/ -->

pg_sage serves the Prometheus text format on ` + "`/metrics`" + `: on the separate
listener (` + "`prometheus.listen_addr`" + `) and, with ` + "`prometheus.serve_on_api`" + `,
on the API port behind a token; [Deployment](deployment.md) shows the scrape
configuration.

Every family pg_sage exports is listed here. **Modes** names the operating
modes that render the family ("all" is standalone, fleet and meta). **Since**
is the first release that exported it under this name. A family whose data
does not exist yet (no TLS, no SLOs, no failure so far) has no samples.

Alert rules ship in [` + "`deploy/prometheus/pg_sage.rules.yml`" + `](` + rulesURL +
	"pg_sage.rules.yml" + `),
tested by [` + "`pg_sage.rules_test.yml`" + `](` + rulesURL + "pg_sage.rules_test.yml" + `)
with ` + "`promtool test rules`" + `; each alert links its runbook below.
`

// render returns docs/metrics.md for the registry and the runbooks.
func render(fams []metricsreg.Family, areas []metricsreg.Area,
	retired []metricsreg.Retired, books []runbook) string {
	var b strings.Builder
	b.WriteString(header)
	for _, a := range areas {
		renderArea(&b, a, fams)
	}
	renderRetired(&b, retired)
	b.WriteString("\n## Alert runbooks\n")
	for _, r := range books {
		fmt.Fprintf(&b, "\n### %s\n\n**Severity:** %s. **Fires when:** %s\n\n"+
			"**What to do:** %s\n", r.Alert, r.Severity, r.Fires, r.Do)
	}
	return b.String()
}

func renderArea(b *strings.Builder, a metricsreg.Area, fams []metricsreg.Family) {
	fmt.Fprintf(b, "\n## %s\n\n%s\n\n", a.Title, a.Intro)
	b.WriteString("| Metric | Type | Labels | Unit | Modes | Since | Meaning |\n" +
		"|---|---|---|---|---|---|---|\n")
	for _, f := range fams {
		if f.Area != a.ID {
			continue
		}
		fmt.Fprintf(b, "| `%s` | %s | %s | %s | %s | %s | %s |\n", f.Name, f.Type,
			codeList(f.Labels), dash(f.Unit), modes(f), f.Since, cell(f.Help))
	}
}

// RenamesTable is the old-to-new table of the retired families.
func renamesTable(retired []metricsreg.Retired) string {
	var b strings.Builder
	b.WriteString(renamesStart + "\n\n| Old name | Use instead | Note | Release |\n" +
		"|---|---|---|---|\n")
	for _, r := range retired {
		use := "-"
		if r.Replacement != "" {
			use = "`" + r.Replacement + "`"
		}
		fmt.Fprintf(&b, "| `%s` | %s | %s | %s |\n", r.Name, use, cell(dash(r.Note)),
			r.Release)
	}
	b.WriteString("\n" + renamesEnd + "\n")
	return b.String()
}

func renderRetired(b *strings.Builder, retired []metricsreg.Retired) {
	b.WriteString("\n## Removed and renamed families\n\n" +
		"These names are no longer exported. Update dashboards and alerts to the " +
		"replacement.\n\n")
	b.WriteString(renamesTable(retired))
}

func modes(f metricsreg.Family) string {
	if !f.ModeSpecific() {
		return "all"
	}
	return strings.Join(f.Modes, ", ") + " only"
}

func codeList(items []string) string {
	if len(items) == 0 {
		return "-"
	}
	return "`" + strings.Join(items, "`, `") + "`"
}

func dash(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

// cell keeps a value inside one table cell.
func cell(s string) string { return strings.ReplaceAll(s, "|", `\|`) }
